                    "isSubtle": true,
                    "wrap": true
                }
            ]
        },
        {
            "type": "Container",
            "spacing": "Small",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "Status:",
                                    "weight": "Bolder",
                                    "spacing": "None",
                                    "size": "Large"
                                }
                            ],
                            "verticalContentAlignment": "Center"
                        },
                        {
                            "type": "Column",
                            "width": "auto",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "text": "SCHEDULED",
                                    "color": "Good",
                                    "weight": "Bolder",
                                    "spacing": "None",
                                    "size": "Large"
                                }
                            ],
                            "verticalContentAlignment": "Center"
                        },
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "TextBlock",
                                    "horizontalAlignment": "Center",
                                    "text": "Scheduled by [@{outputs('Get_item')?['body/submitterEmail_text']}](@{outputs('Get_item')?['body/submitterEmail_text']}) on @{formatDateTime(outputs('Get_item')?['body/Created'],'MMMM d, yyyy ''at'' h:mmtt')}",
                                    "isSubtle": true,
                                    "spacing": "None",
                                    "wrap": true
                                }
                            ],
                            "verticalContentAlignment": "Center"
                        }
                    ]
                }
            ]
        },
        {
            "type": "Container",
            "items": [
                {
                    "type": "ColumnSet",
                    "columns": [
                        {
                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "FactSet",
                                    "facts": [
                                        {
                                            "title": "Name:",
                                            "value": "   @{toUpper(outputs('Get_item')?['body/studentName_text'])}"
