                                        },
                                        {
                                            "title": "Role:",
                                            "value": "   @{outputs('Get_item')?['body/reservationRole_text']}"
                                        },
                                        {
                                            "title": "Scenario:",
                                            "value": "   @{outputs('Get_item')?['body/reservationScenario_text']}"
                                        }
                                    ]
                                }
                            ]
                        },
