                            "type": "Column",
                            "width": "stretch",
                            "items": [
                                {
                                    "type": "FactSet",
                                    "facts": [
                                        {
                                            "title": "Class Date:",
                                            "value": "   @{outputs('Get_item')?['body/RecurrenceEndDate']}"
                                        },
                                        {
                                            "title": "Class Time:",
                                            "value": "   @{outputs('Get_item')?['body/RecurrenceTimes']}"
                                        },
                                        {
                                            "title": "Class Location:",
                                            "value": "   @{outputs('Get_item')?['body/reservationRoom_text']} - @{outputs('Get_item')?['body/reservationBuilding_text']}"
