                                "type": "Action.OpenUrl",
                                "url": "https://launcher.myapps.microsoft.com/api/signin/3c9f19d2-1cb5-4bde-a0ff-f984f4e3c242?tenantId=e95f1b23-abaf-45ee-821d-b7ab251ab3bf",
